import React, { useState } from 'react';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { z } from 'zod';

// Create your Zod schema here
const schema = z.object({
  name: z.string().min(1, 'Name is required'),
  email: z.string().email('Invalid email address'),
  age: z.number().min(18, 'Must be at least 18')
});

// Create your FormComponent here
const FormComponent = () => {
  // Initialize React Hook Form with Zod resolver here
  const { register, handleSubmit: formHandleSubmit, formState: { errors } } = useForm({
    resolver: zodResolver(schema)
  });

  // Add useState for submission results here
  const [submissionResults, setSubmissionResults] = useState(null);

  // Define the form submission handler here

  return (
    <div>
      <h1>Form Validation with Zod + React Hook Form</h1>
    </div>
  );
};

export default FormComponent;

